import { defineConfig, devices } from "@playwright/test";

/**
 * The application's address comes from AQA_APP_URL in the .env file, and from
 * nowhere else: not a default here, not a literal in a page object. A missing
 * value stops the run instead of quietly testing some other address.
 */
const appUrl = process.env["AQA_APP_URL"];
if (!appUrl)
  throw new Error(
    "AQA_APP_URL is not set. Put the application's address in the .env file the run uses " +
      '(attestqa: --env ".env.<app>,.env"; plain Playwright: set AQA_APP_URL in the shell).',
  );

/**
 * The agent's workspace for SauceDemo (research/EVALUATION_PLAN.md).
 *
 * The application lives at `AQA_APP_URL` (https://www.saucedemo.com by default). The address is
 * HERE and nowhere else: generated specs navigate relatively, so the same suite
 * runs against another host (or a seeded-fault build) without editing a test.
 * Credentials come from the environment, never from a spec.
 */
export default defineConfig({
  testDir: "tests",
  // pw.run_tests reads the JSON reporter; keep retries at 0, because the
  // verifier treats green as evidence and a flaky pass is not.
  retries: 0,
  // SauceDemo is a hosted site on the public internet, not a local container:
  // a page load can take longer than Playwright's 30 s default for a whole
  // test (20261022T102919Z: AC-1 timed out in page.goto after the suite had
  // been green). More time for the network, not for the assertions.
  timeout: 60_000,
  // A hosted site: one test at a time, as targets.yaml asks.
  workers: 1,
  reporter: process.env["CI"] ? "line" : "list",
  use: {
    navigationTimeout: 45_000,
    baseURL: appUrl,
    // SauceDemo marks its elements with data-test, not data-testid, so getByTestId
    // ("login-button") finds them.
    testIdAttribute: "data-test",
    trace: "retain-on-failure",
    screenshot: "only-on-failure",
  },
  // The installed Chrome; PW_CHANNEL=msedge for Edge, PW_CHANNEL=chromium for
  // Playwright's bundled build.
  projects: [
    {
      name: "chrome",
      use: {
        ...devices["Desktop Chrome"],
        ...(process.env["PW_CHANNEL"] === "chromium"
          ? {}
          : { channel: process.env["PW_CHANNEL"] ?? "chrome" }),
      },
    },
  ],
});

import { test, expect } from "@playwright/test";
import { CartPage } from "../pages/cart.page";

test.describe("Cart and checkout", () => {

  // @story:114
  // @ac:1
  // @design:D1
  // @type:functional
  // @technique:state-transition
  // @llm-generated
  test("AC-1 Cart lists added product with quantity, name and price", async ({ page }, testInfo) => {
    const cartPage = new CartPage(page);

    await test.step("Given I am on the sign-in page", async () => {
      // @bdd2pw lane=rule rule=rule-26
      await cartPage.goto();
    });

    await test.step("When I find the Username field and enter \"standard_user\"", async () => {
      // @bdd2pw lane=llm provider=anthropic model=claude-sonnet-4-6 cached=false governance=sanitised
      await cartPage.usernameInput.fill(process.env["AQA_APP_USER"] ?? "standard_user");
    });

    await test.step("And I find the Password field and enter \"secret_sauce\"", async () => {
      // @bdd2pw lane=llm provider=anthropic model=claude-sonnet-4-6 cached=false governance=sanitised
      await cartPage.passwordInput.fill(process.env["AQA_APP_PASS"] ?? "secret_sauce");
    });

    await test.step("And Click the \"Login\" button", async () => {

      await page.getByTestId("finish").click();
    });

    await test.step("Then the Finish action took effect; thank-you message is shown", async () => {
      await expect(page.getByText("Thank you for your order!").first()).toBeVisible();
    });
  });
});

  // @bdd2pw lane=rule rule=rule-30
  await cartPage.loginButton.click();
});

await test.step("Then the page displays \"Products\"", async () => {
  // @bdd2pw lane=rule rule=rule-50
  await expect(cartPage.page.getByText("Products").first()).toBeVisible();
});

await test.step("When I click the first Add to cart button in the product list", async () => {
  await page.locator(".inventory_item button").first().click();
});

await test.step("Then the cart badge shows \"1\"", async () => {
  // @bdd2pw lane=llm provider=anthropic model=claude-sonnet-4-6 cached=false governance=sanitised
  await expect(page.locator(".shopping_cart_badge").first()).toHaveText("1");
});

await test.step("When I click the cart icon", async () => {
  await page.locator(".shopping_cart_link").first().click();
});

await test.step("Then the page displays \"Your Cart\"", async () => {
  // @bdd2pw lane=rule rule=rule-50
  await expect(cartPage.page.getByText("Your Cart").first()).toBeVisible();
});

await test.step("And the cart item quantity shows \"1\"", async () => {
  // @bdd2pw lane=llm provider=anthropic model=claude-sonnet-4-6 cached=false governance=sanitised
  await expect(page.locator(".cart_quantity").first()).toHaveText("1");

  // @story:117
  // @bug:122
  // @design:D22
  // @type:confirmation
  // @technique:state-transition
  test("AC-1 Error user cannot finish an order", async ({ page }) => {
    test.fail(true, "Bug #122 Active: Error user cannot finish an order");
    const cartPage = new CartPage(page);

    await test.step("Given I am on the sign-in page", async () => {
      await cartPage.goto();
    });

    await test.step("When I sign in as error_user (precondition: login succeeds)", async () => {
      await cartPage.usernameInput.fill("error_user");
      await cartPage.passwordInput.fill(process.env["AQA_APP_PASS"] ?? "secret_sauce");
      await cartPage.loginButton.click();
      await expect(page.getByText("Products").first()).toBeVisible({ timeout: 10000 });
    });

    await test.step("And I add a product and proceed through checkout to the overview", async () => {
      await page.locator(".inventory_item button").first().click();
      await page.locator(".shopping_cart_link").first().click();
      await expect(page.getByText("Your Cart").first()).toBeVisible();
      await page.getByTestId("checkout").click();
      await expect(page.getByText("Checkout: Your Information").first()).toBeVisible();
      await page.getByTestId("firstName").fill("Jane");
      await page.getByTestId("lastName").fill("Doe");
      await page.getByTestId("postalCode").fill("12345");
      await page.getByTestId("continue").click();
      await expect(page.getByText("Checkout: Overview").first()).toBeVisible();
    });

    await test.step("When I click Finish", async () => {
      await page.getByTestId("finish").click();
    });

    await test.step("Then the Finish action took effect; thank-you message is shown", async () => {
      await expect(page.getByText("Thank you for your order!").first()).toBeVisible();
    });
  });
});

